    add("    def exportar_dados_excel(self, alvos=None):")
    add("        try:")
    add("            from openpyxl import Workbook")
    add("        except ImportError:")
    add("            messagebox.showerror('Excel', 'Para exportar arquivos .xlsx, instale a biblioteca openpyxl com: pip install openpyxl')")
    add("            return")
    add("        nomes = list(alvos or [])")
    add("        if not nomes:")
    add("            nomes = [nome for nome, widget in self.__dict__.items() if isinstance(widget, (ttk.Treeview, tk.Listbox))]")
    add("        fontes = [(nome, getattr(self, nome, None)) for nome in nomes]")
    add("        fontes = [(nome, widget) for nome, widget in fontes if isinstance(widget, (ttk.Treeview, tk.Listbox))]")
    add("        if not fontes:")
    add("            messagebox.showwarning('Excel', 'Selecione uma Treeview ou uma Listbox nos Campos da ação.')")
    add("            return")
    add("        caminho = filedialog.asksaveasfilename(parent=self, title='Exportar para Excel', defaultextension='.xlsx', filetypes=[('Arquivo do Excel', '*.xlsx')])")
    add("        if not caminho:")
    add("            return")
    add("        wb = Workbook()")
    add("        wb.remove(wb.active)")
    add("        def valor_seguro(valor):")
    add("            if isinstance(valor, str) and valor[:1] in ('=', '+', '-', '@'):")
    add("                return \"'\" + valor")
    add("            return valor")
    add("        for indice, (nome, widget) in enumerate(fontes, 1):")
    add("            titulo = re.sub(r'[:\\\\/?*\\[\\]]', '_', str(nome))[:31] or f'Dados{indice}'")
    add("            base = titulo")
    add("            contador = 2")
    add("            while titulo in wb.sheetnames:")
    add("                sufixo = f'_{contador}'")
    add("                titulo = base[:31-len(sufixo)] + sufixo")
    add("                contador += 1")
    add("            ws = wb.create_sheet(titulo)")
    add("            if isinstance(widget, ttk.Treeview):")
    add("                colunas = list(widget['columns'])")
    add("                cabecalhos = [widget.heading(coluna, 'text') or str(coluna) for coluna in colunas]")
    add("                ws.append(cabecalhos)")
    add("                for item in widget.get_children():")
    add("                    ws.append([valor_seguro(v) for v in widget.item(item, 'values')])")
    add("            else:")
    add("                ws.append(['Item'])")
    add("                for item in widget.get(0, tk.END):")
    add("                    ws.append([valor_seguro(item)])")
    add("            for coluna in ws.columns:")
    add("                letra = coluna[0].column_letter")
    add("                maior = max((len(str(celula.value or '')) for celula in coluna), default=10)")
    add("                ws.column_dimensions[letra].width = min(max(maior + 2, 12), 60)")
    add("        try:")
    add("            wb.save(caminho)")
    add("        except OSError as erro:")
    add("            messagebox.showerror('Excel', f'Não foi possível salvar o arquivo: {erro}')")
    add("            return")
    add("        messagebox.showinfo('Excel', 'Dados exportados para o Excel com sucesso!')")
