    add("")
    add("    def _temporizador_tick(self, destino):")
    add("        if not getattr(self, '_temporizador_rodando', False):")
    add("            return")
    add("        restante = int(getattr(self, '_temporizador_restante', 0))")
    add("        self._definir_valor_componente(destino, self._formatar_tempo(restante))")
    add("        if restante <= 0:")
