    add("            messagebox.showinfo('Temporizador', 'Tempo encerrado!')")
    add("            return")
    add("        self._temporizador_restante = restante - 1")
    add("        self.after(1000, lambda: self._temporizador_tick(destino))")
    add("")
    add("    def temporizador_pausar(self, destino):")
    add("        self._temporizador_rodando = False")
    add("        self._definir_valor_componente(destino, self._formatar_tempo(getattr(self, '_temporizador_restante', 0)))")
    add("")
    add("    def temporizador_zerar(self, destino):")
    add("        self._temporizador_rodando = False")
    add("        self._temporizador_restante = 0")
    add("        self._definir_valor_componente(destino, '00:00:00.0')")
