    add("    def calcular_idade_completa(self, origem, destino):")
    add("        texto = str(self._valor_componente(origem)).strip()")
    add("        try:")
    add("            nascimento = datetime.strptime(texto, '%d/%m/%Y').date()")
    add("        except ValueError:")
    add("            messagebox.showwarning('Idade', 'Informe a data de nascimento no formato dd/mm/aaaa.')")
    add("            return")
    add("        hoje = date.today()")
    add("        if nascimento > hoje:")
    add("            messagebox.showwarning('Idade', 'A data de nascimento não pode estar no futuro.')")
    add("            return")
    add("        anos = hoje.year - nascimento.year")
    add("        meses = hoje.month - nascimento.month")
    add("        dias = hoje.day - nascimento.day")
    add("        if dias < 0:")
    add("            meses -= 1")
    add("            mes_anterior = hoje.month - 1 or 12")
    add("            ano_mes_anterior = hoje.year if hoje.month > 1 else hoje.year - 1")
    add("            dias += calendar.monthrange(ano_mes_anterior, mes_anterior)[1]")
    add("        if meses < 0:")
    add("            anos -= 1")
    add("            meses += 12")
    add("        self._definir_valor_componente(destino, f'{anos} anos, {meses} meses e {dias} dias')")
